mapper.select:
SELECT keyword, MAX(create_time) AS create_time
FROM search_history
WHERE user_id = #{userId}
GROUP BY keyword
ORDER BY MAX(create_time) DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM search_history
WHERE user_id = #{userId}
  AND id NOT IN (
    SELECT id FROM (
        SELECT id FROM search_history
        WHERE user_id = #{userId}
        ORDER BY create_time DESC
        LIMIT #{keepCount}
    ) t
  )
